<?php
declare(strict_types=1);
namespace RetroWEB\Infrastructure\Persistence;

final class DeviceSubmissionRepository
{
    private \SQLite3 $db;
    public function __construct(string $path){$dir=dirname($path);if(!is_dir($dir))mkdir($dir,0700,true);$this->db=new \SQLite3($path);$this->db->exec('CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY, device TEXT NOT NULL, browser TEXT NOT NULL, user_agent TEXT NOT NULL, ua_hash TEXT NOT NULL UNIQUE, profile TEXT NOT NULL DEFAULT "generic", verification TEXT NOT NULL DEFAULT "unverified", status TEXT NOT NULL DEFAULT "pending", confirmations INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL)');$columns=[];$result=$this->db->query('PRAGMA table_info(submissions)');while($row=$result->fetchArray(SQLITE3_ASSOC))$columns[]=$row['name'];if(!in_array('profile',$columns,true))$this->db->exec('ALTER TABLE submissions ADD COLUMN profile TEXT NOT NULL DEFAULT "generic"');if(!in_array('verification',$columns,true))$this->db->exec('ALTER TABLE submissions ADD COLUMN verification TEXT NOT NULL DEFAULT "unverified"');$this->db->exec("CREATE TRIGGER IF NOT EXISTS submissions_keep_user_agent BEFORE UPDATE OF user_agent ON submissions WHEN OLD.user_agent<>'' AND NEW.user_agent='' BEGIN SELECT RAISE(ABORT,'Submission User-Agent must be retained'); END");$this->db->exec("CREATE TRIGGER IF NOT EXISTS submissions_require_user_agent BEFORE INSERT ON submissions WHEN NEW.user_agent='' BEGIN SELECT RAISE(ABORT,'Submission User-Agent is required'); END");}
    public function submit(string $device,string $browser,string $observedUa,int $now,string$profile='generic',string$verification='unverified'):int{return$this->submitWithStatus($device,$browser,$observedUa,$now,$profile,$verification)['id'];}
    public function submitWithStatus(string $device,string $browser,string $observedUa,int $now,string$profile='generic',string$verification='unverified'):array{$device=$this->plain($device,80);$browser=$this->plain($browser,80);if($device===''||$observedUa==='')throw new \InvalidArgumentException('Device and observed user-agent are required');if(!preg_match('/^[a-z0-9_]{1,40}$/',$profile)||!in_array($verification,['verified','unverified','ambiguous','unmatched'],true))throw new \InvalidArgumentException('Invalid profile evidence');$hash=hash('sha256',$observedUa);$stmt=$this->db->prepare('SELECT id,status FROM submissions WHERE ua_hash=:hash');$stmt->bindValue(':hash',$hash,SQLITE3_TEXT);$row=$stmt->execute()->fetchArray(SQLITE3_ASSOC);if($row)return['id'=>(int)$row['id'],'new'=>false,'status'=>(string)$row['status']];$stmt=$this->db->prepare('INSERT INTO submissions(device,browser,user_agent,ua_hash,profile,verification,created_at) VALUES(:device,:browser,:ua,:hash,:profile,:verification,:created)');foreach([':device'=>$device,':browser'=>$browser,':ua'=>$observedUa,':hash'=>$hash,':profile'=>$profile,':verification'=>$verification]as$key=>$value)$stmt->bindValue($key,$value,SQLITE3_TEXT);$stmt->bindValue(':created',$now,SQLITE3_INTEGER);$stmt->execute();return['id'=>(int)$this->db->lastInsertRowID(),'new'=>true,'status'=>'pending'];}
    public function moderate(int $id,string $status,?string$profile=null,?string$verification=null):void{if(!in_array($status,['approved','rejected'],true))throw new \InvalidArgumentException('Invalid moderation status');if(($profile===null)!==($verification===null))throw new \InvalidArgumentException('Profile review fields must be supplied together');if($profile!==null&&(!preg_match('/^[a-z0-9_]{1,40}$/',$profile)||!in_array($verification,['verified','unverified','ambiguous','unmatched'],true)))throw new \InvalidArgumentException('Invalid reviewed profile evidence');$sql='UPDATE submissions SET status=:status'.($profile!==null?', profile=:profile, verification=:verification':'').' WHERE id=:id';$stmt=$this->db->prepare($sql);$stmt->bindValue(':status',$status,SQLITE3_TEXT);if($profile!==null){$stmt->bindValue(':profile',$profile,SQLITE3_TEXT);$stmt->bindValue(':verification',$verification,SQLITE3_TEXT);}$stmt->bindValue(':id',$id,SQLITE3_INTEGER);$stmt->execute();if($this->db->changes()!==1)throw new \OutOfBoundsException('Submission not found');}
    public function submission(int$id):?array{$stmt=$this->db->prepare('SELECT id,device,browser,user_agent,profile,verification,status,confirmations,created_at FROM submissions WHERE id=:id');$stmt->bindValue(':id',$id,SQLITE3_INTEGER);$row=$stmt->execute()->fetchArray(SQLITE3_ASSOC);return$row?:null;}
    public function pending():array{return $this->rows('SELECT id,device,browser,user_agent,confirmations,created_at FROM submissions WHERE status="pending" ORDER BY id');}
    public function publicCatalog():array{return $this->rows('SELECT id,device,browser,profile,verification,confirmations FROM submissions WHERE status="approved" ORDER BY device,browser');}
    private function rows(string $sql):array{$result=$this->db->query($sql);$rows=[];while($row=$result->fetchArray(SQLITE3_ASSOC))$rows[]=$row;return$rows;}
    private function plain(string $value,int $max):string{$value=trim(strip_tags($value));$value=preg_replace('/[\x00-\x1F\x7F]/u','',$value);return mb_substr($value,0,$max,'UTF-8');}
}
